/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "btn_fnHomePageJump", fn: function () { return String(dma_digitalInfo.get("hpage")); } },
        { childId: "__rb22", fn: function () { return String(dma_digitalInfo.get("acntclsMm")) + " 월"; } },
        { childId: "btn_fnHomePageJump_2", fn: function () { return String(dma_digitalProdInfo.get("hpageInfo")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.fnInit();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst20011.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_fnHomePageJump_onclick
 * @description btn_fnHomePageJump 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fnHomePageJump_onclick = function(e){
    try {
        scwin.fnHomePageJump('' + dma_digitalInfo.get("hpage") + '');return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst20011.btn_fnHomePageJump_onclick' }); }
};

/**
 * @method
 * @name btn_fnHomePageJump_2_onclick
 * @description btn_fnHomePageJump_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fnHomePageJump_2_onclick = function(e){
    try {
        scwin.fnHomePageJump('' + dma_digitalProdInfo.get("hpageInfo") + '');return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst20011.btn_fnHomePageJump_2_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnInit
 * @description fn Init 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnInit = function () {
    $(document).find('h1[id=title]').empty().append('' + dma_digitalInfo.get("isuKorNm") + '');
    $("#view-name").empty().append('' + dma_digitalInfo.get("secugrpNm") + '');
};

/**
 * @method
 * @name fnHomePageJump
 * @description fn Home Page Jump 처리
 * @param {*} homepage homepage
 * @returns {void}
 * @hidden N
 */
scwin.fnHomePageJump = function (homepage) {
    const home = "http://" + homepage;
